WITH filtered AS (SELECT id, customer_id, browser, started_at, INITCAP(TRIM(country)) AS country_title FROM sessions WHERE started_at > TIMESTAMP '2023-07-05 11:00:00' AND browser IS NOT NULL), prev_events AS (SELECT *, LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) AS prev_started_at FROM filtered), flagged AS (SELECT *, CASE WHEN prev_started_at IS NULL OR started_at > prev_started_at + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM prev_events), islands AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT DATE_TRUNC('MONTH', prev_started_at) AS activity_month, CASE WHEN session_no >= 7 THEN 'HIGH' ELSE 'LOW' END AS session_no_tier, MAX(session_no) FILTER (WHERE browser = 'Safari') AS safari_max_session_no, COUNT(CASE WHEN browser = 'Edge' THEN 1 END) AS edge_count, (UNIX_TIMESTAMP(MAX(prev_started_at)) - UNIX_TIMESTAMP(MIN(prev_started_at))) / 60 AS span_minutes, RANK() OVER (PARTITION BY DATE_TRUNC('MONTH', prev_started_at) ORDER BY MAX(session_no) FILTER (WHERE browser = 'Safari') DESC) AS safari_max_session_no_rank FROM islands GROUP BY activity_month, session_no_tier HAVING safari_max_session_no < 1000000 ORDER BY span_minutes DESC NULLS LAST;
